package main

import (
	"fmt"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.GET("/login", func(c *gin.Context) {
		// 值、maxAge（秒）、path、domain、secure、httpOnly
		c.SetCookie("token", "abc123", 3600, "/", "", false, true)
		c.String(200, "ok")
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/login", nil))
	fmt.Println(w.Header().Get("Set-Cookie"))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.GET("/me", func(c *gin.Context) {
		// Cookie 不存在时返回 http.ErrNoCookie
		token, err := c.Cookie("token")
		if err != nil {
			c.String(http.StatusUnauthorized, "未登录")
			return
		}
		c.String(http.StatusOK, "token="+token)
	})

	req := httptest.NewRequest(http.MethodGet, "/me", nil)
	req.AddCookie(&http.Cookie{Name: "token", Value: "abc123"})
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

