func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.GET("/big", func(c *gin.Context) {
		// 单个 Cookie 的 name+value+属性合计约 4KB，超过会被浏览器丢掉
		c.SetCookie("big", strings.Repeat("a", 4096), 3600, "/", "", false, true)
		c.String(http.StatusOK, "set")
	})

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/big", nil))
	fmt.Println("Set-Cookie 长度:", len(w.Header().Get("Set-Cookie")))
}

