import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"
)

var key = []byte("server-secret")

// 签名 = HMAC-SHA256(key, value)，改动一个字节签名就对不上
func sign(v string) string {
	mac := hmac.New(sha256.New, key)
	mac.Write([]byte(v))
	return hex.EncodeToString(mac.Sum(nil))
}

func main() {
	value := "user=42"
	cookie := value + "|" + sign(value)

	parts := strings.SplitN(cookie, "|", 2)
	// 收到 cookie 后重新算一遍签名再比较
	fmt.Println("校验通过:", hmac.Equal([]byte(sign(parts[0])), []byte(parts[1])))
}

package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
)

// 演示用的内存 session 表，重启就丢；线上要换成 Redis
var (
	mu       sync.Mutex
	sessions = map[string]string{}
)

func newID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.POST("/login", func(c *gin.Context) {
		id := newID()
		mu.Lock()
		sessions[id] = "user-42"
		mu.Unlock()
		// 只把随机 id 交给客户端，用户信息留在服务端
		c.SetCookie("sid", id, 3600, "/", "", false, true)
		c.String(http.StatusOK, "ok")
	})
	r.GET("/me", func(c *gin.Context) {
		id, err := c.Cookie("sid")
		if err != nil {
			c.String(http.StatusUnauthorized, "未登录")
			return
		}
		mu.Lock()
		user, ok := sessions[id]
		mu.Unlock()
		if !ok {
			c.String(http.StatusUnauthorized, "session 已失效")
			return
		}
		c.String(http.StatusOK, user)
	})

	loginW := httptest.NewRecorder()
	r.ServeHTTP(loginW, httptest.NewRequest(http.MethodPost, "/login", nil))
	raw := loginW.Header().Get("Set-Cookie")
	id := strings.TrimPrefix(strings.SplitN(raw, ";", 2)[0], "sid=")
	fmt.Println("登录后 Set-Cookie:", raw)

	// 模拟浏览器下一次请求：把 cookie 带回去
	req := httptest.NewRequest(http.MethodGet, "/me", nil)
	req.AddCookie(&http.Cookie{Name: "sid", Value: id})
	meW := httptest.NewRecorder()
	r.ServeHTTP(meW, req)
	fmt.Println("GET /me ->", meW.Code, meW.Body.String())
}

