import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

const csrfToken = "t0ken"

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.GET("/form", func(c *gin.Context) {
		// 同一份 token 写进 cookie 和页面表单
		c.SetCookie("csrf", csrfToken, 3600, "/", "", false, true)
		c.String(http.StatusOK, csrfToken)
	})
	r.POST("/submit", func(c *gin.Context) {
		// 攻击者能让浏览器自动带 cookie，但读不到 cookie，填不出这个头
		cookie, err := c.Cookie("csrf")
		if err != nil || cookie == "" || cookie != c.GetHeader("X-CSRF-Token") {
			c.String(http.StatusForbidden, "csrf token 不匹配")
			return
		}
		c.String(http.StatusOK, "ok")
	})

	req := httptest.NewRequest(http.MethodPost, "/submit", nil)
	req.Header.Set("X-CSRF-Token", csrfToken)
	req.AddCookie(&http.Cookie{Name: "csrf", Value: csrfToken})
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()
	r.GET("/login", func(c *gin.Context) {
		// 认证相关的 Cookie 一律带 HttpOnly 和 SameSite
		c.SetSameSite(http.SameSiteLaxMode)
		c.SetCookie("sid", "s-123", 3600, "/", "", false, true)
		c.String(http.StatusOK, "登录成功")
	})
	r.GET("/me", func(c *gin.Context) {
		sid, err := c.Cookie("sid")
		if err != nil {
			c.String(http.StatusUnauthorized, "没有 cookie")
			return
		}
		c.JSON(http.StatusOK, gin.H{"sid": sid})
	})

	// 第一步：登录，从响应头里取出 Set-Cookie
	loginW := httptest.NewRecorder()
	r.ServeHTTP(loginW, httptest.NewRequest(http.MethodGet, "/login", nil))
	raw := loginW.Header().Get("Set-Cookie")
	fmt.Println("Set-Cookie:", raw)

	// 第二步：只取 sid=xxx 这一段，塞回下一次请求，模拟浏览器
	value := strings.TrimPrefix(strings.SplitN(raw, ";", 2)[0], "sid=")
	req := httptest.NewRequest(http.MethodGet, "/me", nil)
	req.AddCookie(&http.Cookie{Name: "sid", Value: value})
	meW := httptest.NewRecorder()
	r.ServeHTTP(meW, req)
	fmt.Println("GET /me ->", meW.Code, meW.Body.String())
}
